}

html{scroll-behavior:smooth}
body{
  font-family:'DM Sans',sans-serif;
  background:var(--bg);
  color:var(--text);
  -webkit-font-smoothing:antialiased;
  min-height:100vh;
}

::-webkit-scrollbar{width:4px}
::-webkit-scrollbar-track{background:transparent}
::-webkit-scrollbar-thumb{background:var(--bd2);border-radius:4px}

@keyframes fadeUp{from{opacity:0;transform:translateY(12px)}to{opacity:1;transform:translateY(0)}}
@keyframes fadeIn{from{opacity:0}to{opacity:1}}
@keyframes spin{to{transform:rotate(360deg)}}
@keyframes barGrow{from{width:0%}}
@keyframes recRing{0%{box-shadow:0 0 0 0 rgba(239,68,68,.4)}70%{box-shadow:0 0 0 10px rgba(239,68,68,0)}100%{box-shadow:0 0 0 0 rgba(239,68,68,0)}}
@keyframes shimmer{0%{background-position:-600px 0}100%{background-position:600px 0}}
@keyframes glow{0%,100%{opacity:.6}50%{opacity:1}}
@keyframes pulse{0%,100%{transform:scale(1)}50%{transform:scale(1.06)}}
@keyframes warnPulse{0%,100%{border-color:#f59e0b35}50%{border-color:#f59e0b70}}
@keyframes dashAnim{from{stroke-dashoffset:var(--full,283)}to{stroke-dashoffset:var(--offset,0)}}

/* ── Root ── */
.ch{min-height:100vh;background:var(--bg)}

/* ── Topbar ── */
.ch-bar{
  position:sticky;top:0;z-index:100;
  background:rgba(255,255,255,.92);
  backdrop-filter:blur(20px);
  -webkit-backdrop-filter:blur(20px);
  border-bottom:1px solid var(--bd);
  display:flex;align-items:center;gap:10px;
  padding:0 24px;height:54px;
  box-shadow:0 1px 0 rgba(0,0,0,.06);
}
.ch-bar-logo{
  width:30px;height:30px;border-radius:8px;flex-shrink:0;
  background:var(--accent);
  display:flex;align-items:center;justify-content:center;color:#fff;
  box-shadow:0 2px 8px rgba(45,106,63,.3);
}
.ch-bar-name{
  font-family:'DM Sans',sans-serif;
  font-size:.95rem;font-weight:700;flex:1;
  color:var(--text);letter-spacing:-.01em;
}
.ch-bar-name em{font-style:italic;color:var(--accent);font-weight:400}
.ch-bar-badge{
  font-size:.57rem;font-weight:700;letter-spacing:.1em;text-transform:uppercase;
  padding:3px 10px;border-radius:20px;
  background:var(--accent-bg);color:var(--accent);border:1px solid var(--accent-mid);
  display:flex;align-items:center;gap:5px;
}
.ch-bar-badge-dot{
  width:4px;height:4px;border-radius:50%;background:var(--accent);
  animation:glow 2s ease infinite;
}
.ch-ccgi{
  display:flex;flex-direction:column;align-items:center;justify-content:center;
  width:46px;height:46px;border-radius:50%;
  border:2px solid var(--text);
  font-size:.46rem;font-weight:800;letter-spacing:.08em;
  color:var(--text);line-height:1.1;text-align:center;
  position:relative;
}
.ch-ccgi-sub{
  position:absolute;bottom:-1px;
  font-size:.35rem;letter-spacing:.05em;color:var(--muted);font-weight:600;
}

