  content:'';position:absolute;right:0;top:0;bottom:0;width:45%;pointer-events:none;
  background:
    repeating-linear-gradient(0deg,transparent,transparent 30px,var(--bd) 30px,var(--bd) 31px),
    repeating-linear-gradient(90deg,transparent,transparent 30px,var(--bd) 30px,var(--bd) 31px);
  opacity:.4;
}
.ch-hero-in{
  position:relative;max-width:1060px;margin:0 auto;
  animation:fadeUp .4s ease both;
}
.ch-eyebrow{
  display:inline-flex;align-items:center;gap:6px;
  font-size:.6rem;font-weight:700;letter-spacing:.12em;text-transform:uppercase;
  color:var(--accent);margin-bottom:8px;
}
.ch-eyebrow::before{content:'◆';font-size:.4rem;opacity:.6}
.ch-h1{
  font-family:'DM Serif Display',serif;
  font-size:clamp(1.55rem,3.5vw,2.05rem);line-height:1.1;
  color:var(--text);font-weight:400;
}
.ch-h1 em{font-style:italic;color:var(--accent)}
.ch-sub{font-size:.78rem;color:var(--muted);line-height:1.6;max-width:420px;margin-top:8px}

/* ── Body ── */
.ch-body{
  max-width:1060px;margin:0 auto;
  padding:20px 16px 64px;
}

/* ── 3-Column grid ── */
.ch-grid3{
  display:grid;
  grid-template-columns:1fr 1fr 1fr;
  gap:14px;
  align-items:start;
}

/* ── Card ── */
.ch-card{
  background:var(--white);
  border:1px solid var(--bd);
  border-radius:var(--r);
  overflow:hidden;
  box-shadow:var(--shadow);
  animation:fadeUp .4s ease both;
  transition:border-color .2s var(--ease),box-shadow .2s var(--ease);
}
.ch-card:hover{box-shadow:var(--shadow2)}
.ch-card-hdr{
  display:flex;align-items:center;gap:8px;
  padding:12px 14px 0;
}
.ch-step-badge{
  font-size:.57rem;font-weight:800;letter-spacing:.1em;text-transform:uppercase;
  color:var(--muted);padding:2px 7px;
  border:1px solid var(--bd2);border-radius:20px;
  background:var(--surf2);flex-shrink:0;
}
.ch-card-lbl{
  font-size:.6rem;font-weight:700;letter-spacing:.1em;
  text-transform:uppercase;color:var(--text2);
}
.ch-card-ico{
  width:26px;height:26px;border-radius:6px;flex-shrink:0;
  background:var(--accent-bg);border:1px solid var(--accent-mid);
  display:flex;align-items:center;justify-content:center;color:var(--accent);
}
.ch-card-body{padding:12px 14px 14px}

/* ── Textarea ── */
.ch-ta-wrap{position:relative}
.ch-ta{
  width:100%;min-height:108px;
  background:var(--surf2);color:var(--text);
  border:1px solid var(--bd2);border-radius:var(--r2);
  padding:11px 46px 11px 12px;resize:none;outline:none;
  font-family:'DM Sans',sans-serif;font-size:.84rem;line-height:1.65;
  transition:border-color .2s var(--ease),box-shadow .2s var(--ease);
}
.ch-ta::placeholder{color:var(--dim);font-size:.78rem}
.ch-ta:focus{border-color:var(--accent);box-shadow:0 0 0 3px rgba(45,106,63,.1)}

/* ── Mic ── */
.ch-mic{
  position:absolute;right:9px;bottom:9px;
  width:30px;height:30px;border-radius:50%;
  border:1px solid var(--bd2);cursor:pointer;
  display:flex;align-items:center;justify-content:center;
  transition:all .2s var(--ease);
}
.ch-mic.idle{background:var(--white);color:var(--muted)}
.ch-mic.idle:hover{border-color:var(--accent);color:var(--accent);background:var(--accent-bg)}
.ch-mic.rec{background:#ef4444;color:#fff;border:1px solid #ef4444;animation:recRing 1.4s infinite}

/* ── Hint ── */
.ch-hint{
  display:flex;align-items:center;gap:5px;
  font-size:.62rem;color:var(--muted);margin-top:6px;
}

/* ── Speak Zone ── */
.ch-speak{
  background:var(--surf2);border:1px solid var(--bd);border-radius:var(--r2);
  padding:14px;display:flex;flex-direction:column;align-items:center;gap:7px;
  margin-top:10px;cursor:pointer;transition:border-color .2s var(--ease);
}
.ch-speak:hover{border-color:var(--accent-mid)}
.ch-speak.active{border-color:#ef4444;background:#fff8f8}
.ch-speak-label{font-size:.67rem;font-weight:600;letter-spacing:.06em;text-transform:uppercase;color:var(--muted)}
.ch-speak-circle{
  width:42px;height:42px;border-radius:50%;
  background:var(--accent);color:#fff;
  display:flex;align-items:center;justify-content:center;
  box-shadow:0 4px 14px rgba(45,106,63,.3);
  transition:all .2s var(--ease);
}
.ch-speak.active .ch-speak-circle{background:#ef4444;box-shadow:0 4px 14px rgba(239,68,68,.3)}
.ch-speak-sub{font-size:.63rem;color:var(--muted)}

/* ── Button ── */
.ch-btn{
  width:100%;padding:11px 16px;margin-top:10px;
  border:none;border-radius:var(--r2);cursor:pointer;
  font-family:'DM Sans',sans-serif;font-size:.86rem;font-weight:700;
  display:flex;align-items:center;justify-content:center;gap:7px;
  position:relative;overflow:hidden;transition:all .2s var(--ease);
  letter-spacing:.01em;
}
.ch-btn.on{
  background:var(--accent);color:#fff;
  box-shadow:0 3px 14px rgba(45,106,63,.28);
}
.ch-btn.on:hover{background:#235432;transform:translateY(-1px);box-shadow:0 5px 18px rgba(45,106,63,.35)}
.ch-btn.on:active{transform:translateY(0)}
.ch-btn.off{background:var(--surf2);color:var(--muted);cursor:not-allowed;border:1px solid var(--bd2)}
.ch-shimmer{
  position:absolute;inset:0;
  background:linear-gradient(90deg,transparent,rgba(255,255,255,.18),transparent);
  background-size:600px 100%;animation:shimmer 1.6s infinite;
}

/* ── Spinners ── */
.ch-spin{width:14px;height:14px;border-radius:50%;border:2px solid rgba(255,255,255,.3);border-top-color:#fff;animation:spin .7s linear infinite}
.ch-spin-g{width:14px;height:14px;border-radius:50%;border:2px solid var(--bd2);border-top-color:var(--accent);animation:spin .7s linear infinite}

/* ── Loading ── */
.ch-loading{
  display:flex;align-items:center;gap:10px;
  background:var(--white);border:1px solid var(--bd);
  border-radius:var(--r);padding:12px 14px;
  font-size:.8rem;color:var(--muted);animation:fadeIn .25s ease;
  box-shadow:var(--shadow);margin-top:12px;
}

/* ── Error ── */
.ch-err{
  background:#fff5f5;border:1px solid #fcc;
  border-radius:var(--r);padding:13px 15px;animation:fadeUp .3s ease;
  margin-top:12px;
}
.ch-err-hd{display:flex;align-items:center;gap:7px;font-size:.78rem;font-weight:700;color:#c55;margin-bottom:5px}
.ch-err-bd{font-size:.76rem;color:#a66;line-height:1.55}
.ch-err-tip{font-size:.7rem;color:#c88;margin-top:5px}

/* ── Warning banner ── */
.ch-warn{
  background:#fffbf0;border:1px solid #f59e0b40;
  border-radius:var(--r);padding:13px 15px;
  animation:fadeUp .35s ease,warnPulse 2.5s ease infinite;
  box-shadow:var(--shadow);
}
.ch-warn-hd{display:flex;align-items:center;gap:8px;font-size:.79rem;font-weight:700;color:#b45309;margin-bottom:5px}
.ch-warn-msg{font-size:.76rem;color:#92400e;line-height:1.6;margin-bottom:10px}
.ch-warn-progress{background:#fef3c7;border-radius:6px;height:5px;overflow:hidden;margin-bottom:8px}
.ch-warn-fill{height:100%;background:linear-gradient(90deg,#f59e0b,#d97706);border-radius:6px;transition:width .6s cubic-bezier(.34,1.56,.64,1)}
.ch-warn-sub{font-size:.69rem;color:#92400e;line-height:1.55}
.ch-warn-missing{display:flex;flex-wrap:wrap;gap:5px;margin-top:7px}
.ch-warn-tag{
  font-size:.62rem;font-weight:600;padding:3px 9px;border-radius:20px;
  background:#fef3c7;border:1px solid #f59e0b40;color:#b45309;
  display:flex;align-items:center;gap:4px;
}

/* ── Pills (Detected values) ── */
.ch-pills{display:grid;grid-template-columns:1fr 1fr;gap:8px}
.ch-pill{
  background:var(--white);border:1px solid var(--bd);border-radius:var(--r2);
  padding:9px 11px;animation:fadeUp .3s ease both;
  transition:border-color .2s var(--ease),box-shadow .2s var(--ease);
}
.ch-pill:hover{border-color:var(--accent-mid);box-shadow:var(--shadow)}
.ch-pill-lbl{
  display:flex;align-items:center;gap:4px;
  font-size:.55rem;font-weight:700;letter-spacing:.09em;
  text-transform:uppercase;color:var(--muted);margin-bottom:3px;
}
.ch-pill-lbl svg{color:var(--accent);opacity:.8}
.ch-pill-val{font-size:.84rem;font-weight:700;color:var(--text);line-height:1.2}
.ch-pill-src{font-size:.54rem;color:var(--dim);margin-top:2px}

/* ── Section divider ── */
.ch-div{
  display:flex;align-items:center;gap:10px;
  font-size:.58rem;font-weight:700;letter-spacing:.12em;
  text-transform:uppercase;color:var(--muted);
  animation:fadeUp .35s ease both;
  margin:14px 0 10px;
}
.ch-div::before,.ch-div::after{content:'';flex:1;height:1px;background:var(--bd)}

/* ── Verdict banner ── */
.ch-verdict-banner{
  border-radius:var(--r2);padding:14px 16px;
  display:flex;align-items:center;gap:12px;
  animation:fadeUp .4s ease;
  margin-bottom:10px;
}
.ch-verdict-ico-wrap{
  width:40px;height:40px;border-radius:10px;flex-shrink:0;
  display:flex;align-items:center;justify-content:center;
  background:rgba(255,255,255,.2);
}
.ch-verdict-label{font-size:1.05rem;font-weight:800;line-height:1.1;letter-spacing:-.01em}
.ch-verdict-sub{font-size:.71rem;line-height:1.5;opacity:.85;margin-top:4px}

/* ── Harvest diagram ── */
.ch-diagram{
  background:var(--surf2);border:1px solid var(--bd);
  border-radius:var(--r2);padding:11px;margin-bottom:10px;
}
.ch-diagram-title{font-size:.58rem;font-weight:700;letter-spacing:.09em;text-transform:uppercase;color:var(--muted);margin-bottom:7px}

/* ── Confidence gauges ── */
.ch-conf-gauges{
  display:grid;grid-template-columns:repeat(3,1fr);gap:6px;
}
.ch-conf-gauge{display:flex;flex-direction:column;align-items:center;gap:3px}
.ch-conf-gauge-name{font-size:.6rem;font-weight:600;color:var(--muted);text-align:center;line-height:1.25}
.ch-conf-gauge-name.active{color:var(--text2)}

/* ── Confidence bars (fallback) ── */
.ch-conf-row{display:flex;align-items:center;gap:10px;margin-bottom:10px}
.ch-conf-row:last-child{margin-bottom:0}
.ch-conf-name{width:100px;font-size:.72rem;color:var(--muted);font-weight:500;flex-shrink:0}
.ch-conf-track{flex:1;height:5px;background:var(--surf2);border-radius:5px;overflow:hidden}
.ch-conf-fill{height:100%;border-radius:5px;animation:barGrow .9s cubic-bezier(.34,1.56,.64,1) both}
.ch-conf-pct{width:34px;text-align:right;font-size:.72rem;font-weight:700;font-variant-numeric:tabular-nums}

/* ── Analysis grid (below 3-col) ── */
.ch-analysis-grid{
  display:grid;
  grid-template-columns:1fr 1fr;
  gap:14px;
  align-items:start;
  margin-top:14px;
}

/* ── Bar chart ── */
.ch-bar-charts{display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-top:4px}
.ch-bar-chart-title{font-size:.62rem;font-weight:700;letter-spacing:.07em;text-transform:uppercase;color:var(--text2);margin-bottom:8px;line-height:1.35}
.ch-bars-wrap{display:flex;align-items:flex-end;gap:6px;height:72px}
.ch-bar-col{flex:1;display:flex;flex-direction:column;align-items:center;gap:3px}
.ch-bar-col-bar{width:100%;border-radius:3px 3px 0 0;min-height:3px;transition:height .5s cubic-bezier(.34,1.56,.64,1)}
.ch-bar-col-lbl{font-size:.54rem;color:var(--muted);text-align:center;white-space:nowrap}
.ch-bar-col-val{font-size:.59rem;font-weight:700;color:var(--text2)}
.ch-bar-unit{font-size:.55rem;color:var(--dim);margin-top:3px}

/* ── Reasons ── */
.ch-reasons{display:flex;flex-direction:column;gap:7px}
.ch-reason{
  display:flex;gap:9px;align-items:flex-start;
  background:var(--surf2);border:1px solid var(--bd);
  border-radius:var(--r2);padding:10px 12px;
  animation:fadeUp .35s ease both;transition:border-color .2s var(--ease);cursor:pointer;
}
.ch-reason:hover{border-color:var(--accent-mid)}
.ch-reason-dot{
  width:14px;height:14px;border-radius:50%;flex-shrink:0;margin-top:1px;
  background:var(--accent-bg);border:1.5px solid var(--accent-mid);
  display:flex;align-items:center;justify-content:center;
}
.ch-reason-dot::after{
  content:'';width:5px;height:5px;border-radius:50%;background:var(--accent);display:block;
}
.ch-reason-content{flex:1;min-width:0}
.ch-reason-txt{font-size:.76rem;line-height:1.58;color:var(--text2)}
.ch-reason-chevron{font-size:.68rem;color:var(--dim);flex-shrink:0;margin-top:2px;transition:transform .2s}
.ch-reason.open .ch-reason-chevron{transform:rotate(180deg)}

/* ── Action buttons ── */
.ch-action-row{display:flex;gap:9px;margin-top:12px}
.ch-btn-outline{
  flex:1;padding:11px 16px;border-radius:var(--r2);cursor:pointer;
  font-family:'DM Sans',sans-serif;font-size:.86rem;font-weight:700;
  display:flex;align-items:center;justify-content:center;gap:7px;
  background:var(--white);color:var(--text);
  border:1.5px solid var(--text);
  transition:all .2s var(--ease);
}
.ch-btn-outline:hover{background:var(--text);color:#fff}

/* ── Footer ── */
.ch-footer{
  text-align:center;font-size:.64rem;color:var(--muted);
  margin-top:12px;padding-bottom:10px;line-height:1.65;
  animation:fadeUp .5s ease both;
}

/* ── Responsive ── */
@media(min-width:860px){
  .ch-bar{padding:0 32px}
  .ch-hero{padding:32px 32px 26px}
  .ch-body{padding:22px 24px 72px}
}
@media(max-width:820px){
  .ch-grid3{grid-template-columns:1fr}
  .ch-analysis-grid{grid-template-columns:1fr}
}
@media(max-width:520px){
  .ch-pills{grid-template-columns:1fr 1fr}
  .ch-conf-gauges{grid-template-columns:repeat(3,1fr)}
  .ch-bar-charts{grid-template-columns:1fr}
  .ch-action-row{flex-direction:column}
  .ch-btn-outline{width:100%}
  .ch-bar-badge{display:none}
  .ch-ccgi{width:36px;height:36px;font-size:.4rem}
}
