import { useState, useRef, useCallback, useEffect } from 'react';

const API_BASE = 'http://localhost:5001';

// ─── Field metadata ────────────────────────────────────────────────────────────
const FIELD_META = {
  shoot_height_cm:        { label: 'Shoot Height',        unit: 'cm',  icon: 'height'   },
  trunk_circumference_cm: { label: 'Trunk Circumference', unit: 'cm',  icon: 'trunk'    },
  shoot_age_months:       { label: 'Shoot Age',           unit: 'mo',  icon: 'calendar' },
  num_leaves:             { label: 'Leaf Count',          unit: '',    icon: 'leaf'      },
  ccgi_score:             { label: 'CCGI Score',          unit: '',    icon: 'score'     },
  leaf_color:             { label: 'Leaf Colour',         unit: '',    icon: 'palette'   },
  bark_texture:           { label: 'Bark Texture',        unit: '',    icon: 'texture'   },
  bark_color:             { label: 'Bark Colour',         unit: '',    icon: 'palette'   },
  straightness:           { label: 'Straightness',        unit: '',    icon: 'straight'  },
};

// ─── Verdict config ────────────────────────────────────────────────────────────
const VERDICT = {
  'Ready': {
    label: 'Ready for Harvest',
    sub:   'Coppice at 6 cm from ground at a 45° angle for best yield.',
    icon:  'check',
    accent: '#22c55e', dim: '#166534',
    bg: 'linear-gradient(135deg,#22c55e14 0%,#22c55e07 100%)',
    border: '#22c55e35',
    ring: '0 0 0 1px #22c55e30,0 8px 32px #22c55e25',
  },
  'Nearly Ready': {
    label: 'Nearly Ready',
    sub:   'Re-assess in 2–4 weeks. Key indicators are improving.',
    icon:  'clock',
    accent: '#f59e0b', dim: '#92400e',
    bg: 'linear-gradient(135deg,#f59e0b14 0%,#f59e0b07 100%)',
    border: '#f59e0b35',
    ring: '0 0 0 1px #f59e0b30,0 8px 32px #f59e0b20',
  },
  'Not Ready': {
    label: 'Not Ready Yet',
    sub:   'The shoot needs more time. Check again in a month.',
    icon:  'xc',
    accent: '#60a5fa', dim: '#1e3a5f',
    bg: 'linear-gradient(135deg,#60a5fa14 0%,#60a5fa07 100%)',
    border: '#60a5fa35',
    ring: '0 0 0 1px #60a5fa30,0 8px 32px #60a5fa20',
  },
};

const CONF_BARS = [
  { key: 'Ready',        color: '#22c55e' },
  { key: 'Nearly Ready', color: '#f59e0b' },
  { key: 'Not Ready',    color: '#60a5fa' },
];

