function Loading({ msg }) {
  if (!msg) return null;
  return (
    <div className="ch-loading" style={{ gridColumn: '1 / -1' }}>
      <div className="ch-spin-g"/>
      <span>{msg}</span>
    </div>
  );
}

function ErrorCard({ error }) {
  if (!error) return null;
  return (
    <div className="ch-err" style={{ gridColumn: '1 / -1' }}>
      <div className="ch-err-hd"><Icon name="xc" size={14}/>Connection Error</div>
