// ── Confidence Warning Banner ───────────────────────────────────────────────────
function WarningBanner({ warning }) {
  if (!warning || !warning.low_confidence) return null;
  const pct = warning.completeness_pct ?? 0;
  return (
    <div className="ch-warn">
      <div className="ch-warn-hd">
        <Icon name="warning" size={14}/>
        Low Confidence — Partial Data
      </div>
      <div className="ch-warn-msg">{warning.warning_message}</div>
      <div style={{ display: 'flex', alignItems: 'center', gap: 10, marginBottom: 8 }}>
        <div className="ch-warn-progress" style={{ flex: 1 }}>
          <div className="ch-warn-fill" style={{ width: `${pct}%` }}/>
        </div>
        <span style={{ fontSize: '.68rem', color: '#b45309', fontWeight: 700, width: 32, textAlign: 'right' }}>
          {pct}%
        </span>
      </div>
      {warning.missing_fields?.length > 0 && (
        <>
          <div className="ch-warn-sub">Add these for a more accurate result:</div>
          <div className="ch-warn-missing">
            {warning.missing_fields.map((f, i) => (
              <div className="ch-warn-tag" key={i}>
                <Icon name="plus" size={9}/>{f}
              </div>
            ))}
          </div>
        </>
      )}
    </div>
  );
}

function DetectedFields({ fields }) {
  const entries = Object.entries(fields).filter(([, v]) => v !== null && v !== undefined);
  if (!entries.length) return null;
  return (
    <div className="ch-card" style={{ animationDelay: '.05s' }}>
      <div className="ch-card-hdr">
        <div className="ch-step-badge">2.</div>
        <div className="ch-card-lbl">Detected Data (AI Analysis)</div>
      </div>
      <div className="ch-card-body">
        <div className="ch-pills">
          {entries.map(([k, val], i) => {
            const meta = FIELD_META[k] || { label: k, unit: '', icon: 'info' };
            return (
              <div className="ch-pill" key={k} style={{ animationDelay: `${i * .04}s` }}>
                <div className="ch-pill-lbl">
                  <Icon name={meta.icon} size={9}/>
                  {meta.label}
                </div>
                <div className="ch-pill-val">
                  {String(val)}{meta.unit ? ` ${meta.unit}` : ''}
                </div>
                <div className="ch-pill-src">From text analysis</div>
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
}

// ── Bar chart component ─────────────────────────────────────────────────────────
function BarChart({ title, bars, unit, maxVal }) {
  const max = maxVal || Math.max(...bars.map(b => b.value), 1);
  return (
    <div>
      <div className="ch-bar-chart-title">{title}</div>
      <div className="ch-bars-wrap">
        {bars.map((b, i) => (
          <div className="ch-bar-col" key={i}>
            <div className="ch-bar-col-val">{b.value}</div>
            <div
              className="ch-bar-col-bar"
              style={{ height: `${Math.max((b.value / max) * 58, 3)}px`, background: b.color }}
            />
            <div className="ch-bar-col-lbl">{b.label}</div>
          </div>
        ))}
      </div>
      {unit && <div className="ch-bar-unit">{unit}</div>}
    </div>
  );
}

