          <div className="ch-card-lbl">Result</div>
        </div>
        <div className="ch-card-body">
          {/* Verdict */}
          <div className="ch-verdict-banner" style={{ background: bg }}>
            <div className="ch-verdict-ico-wrap">
              <Icon name={v.icon} size={20} style={{ color: '#fff' }}/>
            </div>
