                ]}
                maxVal={Math.max(160, heightVal)}
              />
              <BarChart
                title={`Trunk circost range${trunkVal ? ` (${trunkVal} cm)` : ''}`}
                unit="circumference in cm"
                bars={[
                  ...(trunkVal ? [{ value: trunkVal, color: '#d97706', label: 'Current' }] : []),
                  { value: 3.9, color: '#b0c0b0', label: 'Part' },
                  { value: 4.5, color: '#dde8dd', label: 'Ideal' },
