}

// ─── Main ─────────────────────────────────────────────────────────────────────
export default function CinnamonHarvest() {
  useCSS();

  const [text,      setText]   = useState('');
  const [loading,   setLoad]   = useState(false);
  const [statusMsg, setMsg]    = useState('');
  const [error,     setError]  = useState('');
  const [fields,    setFields] = useState(null);
  const [result,    setResult] = useState(null);
  const [rec,       setRec]    = useState(false);

  const recRef    = useRef(null);
  const resultRef = useRef(null);

  const toggleVoice = useCallback(() => {
    const SR = window.SpeechRecognition || window.webkitSpeechRecognition;
    if (!SR) { alert('Voice input not supported. Please use Chrome or Edge.'); return; }
    if (rec) { recRef.current?.stop(); setRec(false); return; }
    const r = new SR();
    r.lang = 'en-US'; r.interimResults = true; r.continuous = true;
    recRef.current = r;
    const base = text;
    r.onresult = e => {
      let interim = '', final = base;
      for (const res of e.results) {
        if (res.isFinal) final += (final ? ' ' : '') + res[0].transcript;
        else interim = res[0].transcript;
      }
      setText(final + (interim ? ' ' + interim : ''));
    };
    r.onerror = () => setRec(false);
    r.onend   = () => setRec(false);
    r.start(); setRec(true);
  }, [rec, text]);

  const analyze = useCallback(async () => {
    if (!text.trim() || loading) return;
    setLoad(true); setError(''); setResult(null); setFields(null);
    try {
      setMsg('Reading your description…');
      const pr = await fetch(`${API_BASE}/api/parse`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ text }),
      });
      if (!pr.ok) throw new Error(`Parse failed (${pr.status}): ${await pr.text()}`);
      const parsedFields = (await pr.json()).fields;
      setFields(parsedFields);

      setMsg('Running harvest readiness model…');
      const rr = await fetch(`${API_BASE}/api/predict`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ fields: parsedFields }),
      });
      if (!rr.ok) throw new Error(`Predict failed (${rr.status}): ${await rr.text()}`);
      // Attach fields to result for chart rendering
      const res = await rr.json();
      setResult({ ...res, fields: parsedFields });
      setMsg('');
      setTimeout(() => resultRef.current?.scrollIntoView({ behavior: 'smooth', block: 'start' }), 120);
    } catch (e) {
      setError(e.message); setMsg('');
    } finally {
      setLoad(false);
    }
  }, [text, loading]);

  const handleSave = useCallback(() => {
    alert(`✅ Analysis saved at ${new Date().toLocaleString()}\n\nIn production this saves to your account.`);
  }, []);

  const handleNewScan = useCallback(() => {
    setText(''); setResult(null); setFields(null); setError('');
    window.scrollTo({ top: 0, behavior: 'smooth' });
  }, []);

  return (
    <div className="ch">
      <TopBar/>
      <Hero/>

      <div className="ch-body">
        {/* ── 3-column main grid ── */}
        <div className="ch-grid3">

          {/* Col 1 — Input */}
          <InputCard
            text={text} setText={setText}
            loading={loading} recording={rec}
            onVoice={toggleVoice} onAnalyze={analyze}
          />

          {/* Col 2 — Detected values */}
          {fields ? (
            <DetectedFields fields={fields}/>
          ) : (
            <div className="ch-card" style={{ animationDelay: '.07s' }}>
              <div className="ch-card-hdr">
                <div className="ch-step-badge">2.</div>
                <div className="ch-card-lbl">Detected Data (AI Analysis)</div>
              </div>
              <div className="ch-card-body">
                <div style={{ textAlign: 'center', padding: '28px 0', fontSize: '.75rem', color: 'var(--muted)', lineHeight: 1.7 }}>
                  Enter a shoot description<br/>and click analyse
                </div>
              </div>
            </div>
          )}

          {/* Col 3 — Result (only when available) */}
          {result ? (
            <div ref={resultRef}>
              {/* ResultSection renders col-3 card + analysis grid */}
            </div>
          ) : (
            <div className="ch-card" style={{ animationDelay: '.13s' }}>
              <div className="ch-card-hdr">
                <div className="ch-step-badge">3.</div>
                <div className="ch-card-lbl">Result</div>
              </div>
              <div className="ch-card-body">
                <div style={{ textAlign: 'center', padding: '28px 0', fontSize: '.75rem', color: 'var(--muted)', lineHeight: 1.7 }}>
                  Results will appear here<br/>after analysis
                </div>
              </div>
            </div>
          )}

        </div>{/* /ch-grid3 */}

        {/* Loading */}
        {loading && statusMsg && (
          <Loading msg={statusMsg}/>
        )}

        {/* Error */}
        {error && <ErrorCard error={error}/>}

        {/* Result section (rendered below grid, spans full width) */}
        {result && (
          <div ref={resultRef} style={{ marginTop: 0 }}>
            {/* Re-render col 3 card + analysis in a dedicated wrapper */}
            <div className="ch-grid3" style={{ marginTop: 14 }}>
              <div style={{ gridColumn: '3 / 4' }}>
                <ResultSection
                  result={result}
                  onSave={handleSave}
                  onNewScan={handleNewScan}
                />
              </div>
            </div>
          </div>
        )}

        <div className="ch-footer">
          Cinnamon Harvest AI · Ceylon Cinnamon Growers Institute data<br/>
          For guidance only — confirm with a field agronomist before harvest.
        </div>
      </div>
    </div>
  );
}
